class Cache<T> {
  final List<T> items = [];

  void put(T value) {
    items.add(value);
  }

  T? read() => items.isEmpty ? null : items.last;
}

void main() {
  final names = Cache<String>();
  names.put('林夏');
  final List<String> copy = [...names.items];
  print('${names.read()} ${copy.length}');
}

