Stream<int> ticks() async* {
  for (var i = 1; i <= 2; i++) {
    await Future<void>.delayed(const Duration(milliseconds: 1));
    yield i;
  }
}

Future<void> main() async {
  await for (final n in ticks()) {
    print(n);
  }
}

